+document.addEventListener('DOMContentLoaded', () => {
+    const modal = document.getElementById('deleteModal');
+    const triggers = document.querySelectorAll('.trigger');
+    const closeBtn = document.querySelector('.modal-close');
+    const cancelBtn = document.querySelector('.btn-cancel');
+    const deleteBtn = document.querySelector('.btn-delete');
+    const overlay = document.querySelector('.modal-overlay');
+
+    let currentImageId = null;
+
+    // Open modal when delete button is clicked
+    triggers.forEach(trigger => {
+        trigger.addEventListener('click', (e) => {
+            e.preventDefault();
+            currentImageId = trigger.getAttribute('data-image-id');
+            modal.removeAttribute('hidden');
+        });
+    });
+
+    // Close modal functions
+    const closeModal = () => {
+        modal.setAttribute('hidden', '');
+        currentImageId = null;
+    };
+
+    // Close button click
+    closeBtn.addEventListener('click', closeModal);
+
+    // Cancel button click
+    cancelBtn.addEventListener('click', closeModal);
+
+    // Overlay click to close
+    overlay.addEventListener('click', closeModal);
+
+    // Delete button click
+    deleteBtn.addEventListener('click', () => {
+        if (currentImageId) {
+            console.log(`Image ${currentImageId} deleted`);
+            // Find and remove the image card
+            const trigger = document.querySelector(`[data-image-id="${currentImageId}"]`);
+            if (trigger) {
+                const card = trigger.closest('.image-card');
+                if (card) {
+                    card.style.animation = 'fadeOut 0.3s ease-out';
+                    setTimeout(() => {
+                        card.remove();
+                    }, 300);
+                }
+            }
+        }
+        closeModal();
+    });
+
+    // Close modal with Escape key
+    document.addEventListener('keydown', (e) => {
+        if (e.key === 'Escape' && !modal.hasAttribute('hidden')) {
+            closeModal();
+        }
+    });
+});
+
+// Add fade out animation
+const style = document.createElement('style');
+style.textContent = `
+    @keyframes fadeOut {
+        from {
+            opacity: 1;
+            transform: scale(1);
+        }
+        to {
+            opacity: 0;
+            transform: scale(0.95);
+        }
+    }
+`;
+document.head.appendChild(style);
+
